package security

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const autoCaddy = `#
# Configuration generated by "cscli setup".
# cscli-checksum: 6cc8a30c
journalctl_filter:
  - _SYSTEMD_UNIT=caddy.service
labels:
  type: syslog
source: journalctl
`

const autoLinux = `#
# Configuration generated by "cscli setup".
filenames:
  - /var/log/messages
  - /var/log/syslog
  - /var/log/kern.log
labels:
  type: syslog
source: file
`

func testWebPaths(t *testing.T) webPaths {
	t.Helper()
	root := t.TempDir()
	paths := webPaths{
		acquisDir: filepath.Join(root, "acquis.d"),
		acquisLegacy: filepath.Join(root, "acquis.yaml"),
		rsyslogDir: filepath.Join(root, "rsyslog.d"),
	}
	for _, dir := range []string{paths.acquisDir, paths.rsyslogDir} {
		if err := os.MkdirAll(dir, 0755); err != nil {
			t.Fatal(err)
		}
	}
	return paths
}

func putTestConfig(t *testing.T, path, data string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(data), 0644); err != nil {
		t.Fatal(err)
	}
}

func readTestConfig(t *testing.T, path string) string {
	t.Helper()
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(content)
}

func fakeWebExecutables(t *testing.T) {
	t.Helper()
	dir := t.TempDir()
	scripts := map[string]string{
		"crowdsec": "#!/bin/sh\necho crowdsec >> \"$WEB_COMMAND_LOG\"\nif [ \"$FAIL_CROWDSEC_VALIDATE\" = 1 ]; then exit 1; fi\nexit 0\n",
		"rsyslogd": "#!/bin/sh\necho rsyslog-validate >> \"$WEB_COMMAND_LOG\"\nif [ \"$FAIL_RSYSLOG_VALIDATE\" = 1 ]; then exit 1; fi\nexit 0\n",
		"systemctl": "#!/bin/sh\necho \"systemctl $*\" >> \"$WEB_COMMAND_LOG\"\nif [ \"$1\" = restart ] && [ \"$FAIL_SERVICE\" = \"$2\" ]; then exit 1; fi\nexit 0\n",
	}
	for name, body := range scripts {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0755); err != nil {
			t.Fatal(err)
		}
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("WEB_COMMAND_LOG", filepath.Join(dir, "commands"))
}

func TestInspectWebSourcesFromRealWorldConfiguration(t *testing.T) {
	p := testWebPaths(t)
	putTestConfig(t, filepath.Join(p.acquisDir, "setup.caddy.yaml"), autoCaddy)
	putTestConfig(t, filepath.Join(p.acquisDir, "setup.linux.yaml"), autoLinux)
	putTestConfig(t, filepath.Join(p.acquisDir, "setup.sshd.yaml"),
		"source: file\nfilenames:\n  - /var/log/auth.log\nlabels:\n  type: syslog\n")
	putTestConfig(t, p.panelSource(), panelCaddyAcquisition)

	got, err := inspectWebSources(p)
	if err != nil {
		t.Fatal(err)
	}
	if !got.Panel || len(got.External) != 1 || !got.SyslogAcquired || !got.NeedsRepair || !got.HasCaddy() {
		t.Fatalf("expected all three overlapping sources detected: %+v", got)
	}
	if !got.ExternallyManaged() {
		t.Fatalf("external source not identified: %+v", got)
	}
	if documentCaddyJournal(autoLinux) ||
		documentCaddyJournal("source: journalctl\njournalctl_filter:\n - _SYSTEMD_UNIT=ssh.service\nlabels:\n type: syslog\n") ||
		documentCaddyJournal("# source: journalctl\n# _SYSTEMD_UNIT=caddy.service\n# type: syslog\n") {
		t.Fatal("wrongly detected a Caddy source")
	}
}

func TestRepairWebSourcesKeepsCrowdSecOwnedConfigurationAndSSH(t *testing.T) {
	fakeWebExecutables(t)
	p := testWebPaths(t)
	setupPath := filepath.Join(p.acquisDir, "setup.caddy.yaml")
	linuxPath := filepath.Join(p.acquisDir, "setup.linux.yaml")
	sshPath := filepath.Join(p.acquisDir, "setup.sshd.yaml")
	putTestConfig(t, setupPath, autoCaddy)
	putTestConfig(t, linuxPath, autoLinux)
	putTestConfig(t, sshPath, "source: file\nfilenames:\n  - /var/log/auth.log\n")
	putTestConfig(t, p.panelSource(), panelCaddyAcquisition)
	if err := repairCaddyAcquisition(context.Background(), p); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(p.panelSource()); !os.IsNotExist(err) {
		t.Fatalf("panel's duplicate acquisition still exists: %v", err)
	}
	if readTestConfig(t, setupPath) != autoCaddy ||
		readTestConfig(t, linuxPath) != autoLinux ||
		readTestConfig(t, sshPath) != "source: file\nfilenames:\n  - /var/log/auth.log\n" {
		t.Fatal("CrowdSec-generated or SSH acquisition modified")
	}
	if readTestConfig(t, p.syslogFilter()) != panelCaddyRsyslog {
		t.Fatal("missing selective rsyslog Caddy HTTP filter")
	}
	got, err := inspectWebSources(p)
	if err != nil || !got.HasCaddy() || got.Panel || got.NeedsRepair || !got.SyslogFiltered {
		t.Fatalf("repair ineffective: %+v, %v", got, err)
	}
	log := readTestConfig(t, os.Getenv("WEB_COMMAND_LOG"))
	for _, expected := range []string{"rsyslog-validate", "systemctl restart rsyslog.service", "crowdsec", "systemctl restart crowdsec.service"} {
		if !strings.Contains(log, expected) {
			t.Errorf("missing step %q from %s", expected, log)
		}
	}
	if err := repairCaddyAcquisition(context.Background(), p); err != nil {
		t.Fatalf("repair must be idempotent: %v", err)
	}
}

func TestRepairWebSourcesRollsBackOnValidationError(t *testing.T) {
	fakeWebExecutables(t)
	p := testWebPaths(t)
	setupPath := filepath.Join(p.acquisDir, "setup.caddy.yaml")
	putTestConfig(t, setupPath, autoCaddy)
	putTestConfig(t, filepath.Join(p.acquisDir, "setup.linux.yaml"), autoLinux)
	putTestConfig(t, p.panelSource(), panelCaddyAcquisition)
	t.Setenv("FAIL_RSYSLOG_VALIDATE", "1")
	if err := repairCaddyAcquisition(context.Background(), p); err == nil {
		t.Fatal("expected rsyslog validation to fail")
	}
	if readTestConfig(t, p.panelSource()) != panelCaddyAcquisition {
		t.Fatal("duplicate acquisition not restored after validation error")
	}
	if _, err := os.Stat(p.syslogFilter()); !os.IsNotExist(err) {
		t.Fatal("new rsyslog rule not removed on error")
	}
	if readTestConfig(t, setupPath) != autoCaddy {
		t.Fatal("external setup changed")
	}
}

func TestRepairWebSourcesPreservesCustomFilesAndNoExternalFallback(t *testing.T) {
	fakeWebExecutables(t)
	p := testWebPaths(t)
	putTestConfig(t, p.panelSource(), panelCaddyAcquisition+"# user changes\n")
	if err := repairCaddyAcquisition(context.Background(), p); err == nil {
		t.Fatal("custom acquisition unexpectedly overwritten")
	}
	if err := os.Remove(p.panelSource()); err != nil {
		t.Fatal(err)
	}
	if err := repairCaddyAcquisition(context.Background(), p); err != nil {
		t.Fatal(err)
	}
	if readTestConfig(t, p.panelSource()) != panelCaddyAcquisition {
		t.Fatal("fallback panel Caddy source not created")
	}

	putTestConfig(t, filepath.Join(p.acquisDir, "setup.caddy.yaml"), autoCaddy)
	putTestConfig(t, p.syslogFilter(), "# user-managed rule\n")
	if err := repairCaddyAcquisition(context.Background(), p); err == nil {
		t.Fatal("custom rsyslog configuration unexpectedly overwritten")
	}
	if readTestConfig(t, p.panelSource()) != panelCaddyAcquisition {
		t.Fatal("panel acquisition changed despite failed preflight")
	}
}
